"use server";

import { revalidatePath } from "next/cache";
import { prisma } from "@/lib/prisma";
import { requireAdmin } from "@/lib/session";
import { taskSchema, taskStatusEnum } from "@/lib/validations";
import { Prisma, TaskStatus } from "@prisma/client";

export interface TaskActionResponse {
  error?: string;
  fieldErrors?: Record<string, string>;
  success?: boolean;
}

/**
 * Core transactional creation logic for microtasks.
 * The task ID is automatically generated by Prisma (@default(cuid()))
 * and does not require manual entry.
 */
export async function executeCreateTask(input: {
  title: string;
  description: string;
  taskUrl: string;
  instructions: string;
  rewardInr: string;
  proofRequirements: string;
  proofType?: "TEXT" | "IMAGE" | "BOTH";
  status?: TaskStatus;
  deadline?: string | null;
  maxSubmissions?: string | null;
}): Promise<TaskActionResponse & { taskId?: string }> {
  const validation = taskSchema.safeParse({
    title: input.title,
    description: input.description,
    taskUrl: input.taskUrl,
    instructions: input.instructions,
    rewardInr: input.rewardInr,
    proofRequirements: input.proofRequirements,
    proofType: input.proofType || "BOTH",
    status: input.status || "DRAFT",
    deadline: input.deadline || null,
    maxSubmissions: input.maxSubmissions || null,
  });

  if (!validation.success) {
    const fieldErrors: Record<string, string> = {};
    for (const issue of validation.error.issues) {
      fieldErrors[issue.path[0] as string] = issue.message;
    }
    return { fieldErrors };
  }

  try {
    const created = await prisma.task.create({
      data: {
        title: input.title,
        description: input.description,
        taskUrl: input.taskUrl,
        instructions: input.instructions,
        rewardInr: new Prisma.Decimal(input.rewardInr),
        proofRequirements: input.proofRequirements,
        proofType: input.proofType || "BOTH",
        status: input.status || "DRAFT",
        deadline: input.deadline ? new Date(input.deadline) : null,
        maxSubmissions: input.maxSubmissions ? parseInt(input.maxSubmissions, 10) : null,
      },
    });

    return { success: true, taskId: created.id };
  } catch (error) {
    console.error("Failed to create task:", error);
    return { error: "Failed to create task in database. Please check input values." };
  }
}

export async function createTaskAction(
  prevState: TaskActionResponse,
  formData: FormData
): Promise<TaskActionResponse> {
  // Independent Authorization Barrier
  await requireAdmin();

  const title = (formData.get("title") as string)?.trim() || "";
  const description = (formData.get("description") as string)?.trim() || "";
  const taskUrl = (formData.get("taskUrl") as string)?.trim() || "";
  const instructions = (formData.get("instructions") as string)?.trim() || "";
  const rewardInr = (formData.get("rewardInr") as string)?.trim() || "";
  const proofRequirements = (formData.get("proofRequirements") as string)?.trim() || "";
  const proofType = (formData.get("proofType") as "TEXT" | "IMAGE" | "BOTH") || "BOTH";
  const status = (formData.get("status") as TaskStatus) || "DRAFT";
  const deadlineStr = (formData.get("deadline") as string)?.trim() || "";
  const maxSubmissionsStr = (formData.get("maxSubmissions") as string)?.trim() || "";

  const result = await executeCreateTask({
    title,
    description,
    taskUrl,
    instructions,
    rewardInr,
    proofRequirements,
    proofType,
    status,
    deadline: deadlineStr || null,
    maxSubmissions: maxSubmissionsStr || null,
  });

  if (result.success) {
    revalidatePath("/admin/tasks");
    revalidatePath("/");
  }

  return result;
}

/**
 * Unified save action that automatically routes to either update or create
 * based on whether a taskId is present in the form data.
 */
export async function saveTaskAction(
  prevState: TaskActionResponse,
  formData: FormData
): Promise<TaskActionResponse> {
  const taskId = (formData.get("taskId") as string)?.trim();
  if (taskId) {
    return updateTaskAction(prevState, formData);
  }
  return createTaskAction(prevState, formData);
}

export async function updateTaskAction(
  prevState: TaskActionResponse,
  formData: FormData
): Promise<TaskActionResponse> {
  // Independent Authorization Barrier
  await requireAdmin();

  const taskId = (formData.get("taskId") as string)?.trim();
  if (!taskId) {
    // If taskId is missing, delegate to task creation to prevent blocking the admin
    return createTaskAction(prevState, formData);
  }

  const title = (formData.get("title") as string)?.trim() || "";
  const description = (formData.get("description") as string)?.trim() || "";
  const taskUrl = (formData.get("taskUrl") as string)?.trim() || "";
  const instructions = (formData.get("instructions") as string)?.trim() || "";
  const rewardInr = (formData.get("rewardInr") as string)?.trim() || "";
  const proofRequirements = (formData.get("proofRequirements") as string)?.trim() || "";
  const proofType = (formData.get("proofType") as "TEXT" | "IMAGE" | "BOTH") || "BOTH";
  const deadlineStr = (formData.get("deadline") as string)?.trim() || "";
  const maxSubmissionsStr = (formData.get("maxSubmissions") as string)?.trim() || "";

  const validation = taskSchema.safeParse({
    title,
    description,
    taskUrl,
    instructions,
    rewardInr,
    proofRequirements,
    proofType,
    deadline: deadlineStr || null,
    maxSubmissions: maxSubmissionsStr || null,
  });

  if (!validation.success) {
    const fieldErrors: Record<string, string> = {};
    for (const issue of validation.error.issues) {
      fieldErrors[issue.path[0] as string] = issue.message;
    }
    return { fieldErrors };
  }

  try {
    const existing = await prisma.task.findUnique({ where: { id: taskId } });
    if (!existing) return { error: "Task not found." };

    await prisma.task.update({
      where: { id: taskId },
      data: {
        title,
        description,
        taskUrl,
        instructions,
        rewardInr: new Prisma.Decimal(rewardInr),
        proofRequirements,
        proofType,
        deadline: deadlineStr ? new Date(deadlineStr) : null,
        maxSubmissions: maxSubmissionsStr ? parseInt(maxSubmissionsStr, 10) : null,
      },
    });

    revalidatePath("/admin/tasks");
    revalidatePath(`/tasks/${taskId}`);
    revalidatePath("/");
    return { success: true };
  } catch (error) {
    console.error("Failed to update task:", error);
    return { error: "Failed to update task." };
  }
}

export async function updateTaskStatusAction(
  taskId: string,
  newStatus: TaskStatus
): Promise<TaskActionResponse> {
  // Independent Authorization Barrier
  await requireAdmin();

  if (!taskStatusEnum.safeParse(newStatus).success) {
    return { error: "Invalid task status." };
  }

  try {
    const task = await prisma.task.findUnique({ where: { id: taskId } });
    if (!task) return { error: "Task not found." };

    // Valid state transitions
    await prisma.task.update({
      where: { id: taskId },
      data: { status: newStatus },
    });

    revalidatePath("/admin/tasks");
    revalidatePath(`/tasks/${taskId}`);
    revalidatePath("/");
    return { success: true };
  } catch (error) {
    console.error("Failed to update task status:", error);
    return { error: "Failed to update task status." };
  }
}
